import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        print("")
        return

    arr_set = set(data)
    candidates = []

    for s in data:
        valid = True
        for i in range(1, len(s)):
            if s[:i] not in arr_set:
                valid = False
                break
        if valid:
            candidates.append(s)

    if not candidates:
        print("")
        return

    max_len = -1
    for s in candidates:
        if len(s) > max_len:
            max_len = len(s)

    best = None
    for s in candidates:
        if len(s) == max_len:
            if best is None or s < best:
                best = s

    if best is None:
        print("")
    else:
        print(best)

if __name__ == "__main__":
    main()
